parameters.jsCode:
const raw = $input.first().json.stdout || '';
if (raw.includes('GPU_ERROR') || !raw.trim()) {
  return [{ json: { error: true, message: 'nvidia-smi indisponible', gpus: [], alert: false } }];
}

const gpus = raw.trim().split('\n').map((line, i) => {
  const parts = line.split(',').map(s => s.trim());
  return {
    index: parseInt(parts[0]) || i,
    name: parts[1] || 'GPU',
    temp: parseInt(parts[2]) || 0,
    gpu_util: parseInt(parts[3]) || 0,
    mem_util: parseInt(parts[4]) || 0,
    mem_used: parseInt(parts[5]) || 0,
    mem_total: parseInt(parts[6]) || 0,
    power: parseFloat(parts[7]) || 0
  };
});

const criticals = gpus.filter(g => g.temp >= 85);
const warnings = gpus.filter(g => g.temp >= 75 && g.temp < 85);
const alert = criticals.length > 0;
const warn = warnings.length > 0;

const gpuLines = gpus.map(g => {
  const icon = g.temp >= 85 ? '🔴' : g.temp >= 75 ? '🟠' : '🟢';
  return `${icon} GPU${g.index} (${g.name.replace('NVIDIA ','').replace('GeForce ','')}):\n   🌡️ ${g.temp}°C | ⚡ ${g.gpu_util}% | 🧠 ${g.mem_used}/${g.mem_total}MB | 🔌 ${g.power}W`;
}).join('\n');

const status = criticals.length > 0 ? '🚨 CRITIQUE' : warn ? '⚠️ ATTENTION' : '✅ NOMINAL';
const now = new Date().toLocaleTimeString('fr-FR');

const message = `🖥️ *JARVIS GPU Monitor — ${now}*\n*Statut: ${status}*\n\n${gpuLines}\n\n━━━━━━━━━━━━━━━━\n_Cluster M1 La Creatrice — 5 GPU 40GB VRAM_`;

return [{ json: { gpus, alert, warn, criticals, message, status } }];

